import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.E8pQZ6KS.js";const _=JSON.parse('{"title":"考研与深造","description":"","frontmatter":{},"headers":[],"relativePath":"竞赛与成长/考研与深造.md","filePath":"竞赛与成长/考研与深造.md","lastUpdated":1792430298000}'),o={name:"竞赛与成长/考研与深造.md"};function i(d,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="考研与深造" tabindex="-1">考研与深造 <a class="header-anchor" href="#考研与深造" aria-label="Permalink to &quot;考研与深造&quot;">​</a></h1><blockquote><p>网安是一个「重学历也重实战」的领域。本文整理考研/保研方向的信息与建议，具体政策以学校与目标院校当年通知为准。</p></blockquote><h2 id="保研-推免" tabindex="-1">保研（推免） <a class="header-anchor" href="#保研-推免" aria-label="Permalink to &quot;保研（推免）&quot;">​</a></h2><ul><li><strong>硬指标</strong>：绩点排名 + 英语（四六级）+ 科研/竞赛经历；</li><li>学院「以赛促学」的竞赛成绩在保研评价中占重要权重——尽早参赛并积累奖项；</li><li>大三暑假关注目标院校的<strong>夏令营</strong>（网安相关学院/实验室）。</li></ul><h2 id="考研" tabindex="-1">考研 <a class="header-anchor" href="#考研" aria-label="Permalink to &quot;考研&quot;">​</a></h2><ul><li><strong>考试科目</strong>：通常为政治、英语、数学（一/二）+ 专业课（408 统考或院校自命题，如数据结构、计算机网络、操作系统等）；</li><li>网安考研热度高，建议提前一年启动数学与专业课；</li><li>目标院校可选：网安一级学科院校（如西电、北邮、川大、信工所等，以及双一流综合大学计算机/网安学院），结合自身定位选择。</li></ul><h2 id="保研-考研信息渠道" tabindex="-1">保研/考研信息渠道 <a class="header-anchor" href="#保研-考研信息渠道" aria-label="Permalink to &quot;保研/考研信息渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>说明</th></tr></thead><tbody><tr><td>目标院校研究生院官网</td><td>招生简章、复试方案（权威）</td></tr><tr><td>目标实验室主页</td><td>导师方向与课题组信息</td></tr><tr><td>学长学姐</td><td>一手经验最重要，主动请教</td></tr></tbody></table><h2 id="出国深造-可选" tabindex="-1">出国深造（可选） <a class="header-anchor" href="#出国深造-可选" aria-label="Permalink to &quot;出国深造（可选）&quot;">​</a></h2><ul><li>安全方向海外强校：美国（CMU、Berkeley、MIT 等）、欧洲部分高校；</li><li>需要早做准备：语言成绩、科研经历（进实验室发论文）、推荐信。</li></ul><h2 id="通用建议" tabindex="-1">通用建议 <a class="header-anchor" href="#通用建议" aria-label="Permalink to &quot;通用建议&quot;">​</a></h2><ul><li><strong>科研经历</strong>：大二起申请进入学院实验室（网络安全研究所方向），参与课题或发表论文，对保研、考研复试、出国都极有价值；</li><li>竞赛 + 科研 + 绩点，三条线尽量同时推进；</li><li>无论考研还是保研，<strong>动手能力（CTF/项目）都是复试中的加分项</strong>，别丢下。</li></ul><p>::: note 本页为信息整理与建议，不构成择校决策依据。请结合自身情况咨询辅导员、专业老师与学长学姐。 :::</p>',13)])])}const b=a(o,[["render",i]]);export{_ as __pageData,b as default};
